  or not exists(select 1 from pg_catalog.pg_trigger where tgrelid=rel.oid and tgname='owned_ai_disposition_seal_closed'
    and not tgisinternal and tgenabled='O' and tgfoid=to_regprocedure('private.owned_ai_disposition_seal_closed()') and tgtype=31 and tgnargs=0 and tgqual is null)
  or (select count(*) from pg_catalog.pg_trigger where tgrelid=rel.oid and not tgisinternal)<>1
  or private.owned_ai_disposition_catalogue() is distinct from (select catalogue from private.owned_ai_disposition_catalogue_seal where singleton)
  then return false;end if;
 foreach role_name in array array['anon','authenticated','service_role'] loop
  if has_table_privilege(role_name,rel.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
   or has_any_column_privilege(role_name,rel.oid,'SELECT,INSERT,UPDATE,REFERENCES') then return false;end if;
 end loop;

