  or not exists(select 1 from pg_catalog.pg_trigger where tgrelid='public.resumes'::regclass and tgname='zy_retention_root_tombstone'
   and not tgisinternal and tgenabled='O' and tgfoid=to_regprocedure('private.r17_root_tombstone_guard()') and tgtype=19 and tgnargs=0 and tgqual is null)
  then return false;end if;
 for item in select value from jsonb_array_elements($r17_source_columns$[["public.resume_versions","id","uuid",true],["public.resume_versions","resume_id","uuid",true],["public.resume_versions","organization_id","uuid",true],["public.resume_versions","owner_id","uuid",true],["public.resume_versions","storage_key","text",true],["public.resume_versions","checksum","text",true],["public.resume_versions","bytes","integer",true],["public.resume_versions","media_type","text",true],["public.resume_versions","page_count","integer",false],["public.resume_versions","created_at","timestamp with time zone",true],["public.resume_versions","updated_at","timestamp with time zone",true],["private.retention_items","id","uuid",true],["private.retention_items","resume_id","uuid",true],["private.retention_items","owner_id","uuid",true],["private.retention_items","storage_key","text",true],["private.retention_items","status","text",true],["private.retention_items","attempt_count","integer",true],["private.retention_items","last_error_code","text",false],["private.retention_items","created_at","timestamp with time zone",true],["private.retention_items","completed_at","timestamp with time zone",false]]$r17_source_columns$::jsonb) loop
  if not exists(select 1 from pg_catalog.pg_attribute a join pg_catalog.pg_class c on c.oid=a.attrelid
    where a.attrelid=to_regclass(item->>0) and a.attname=item->>1 and a.atttypid=to_regtype(item->>2) and a.attnotnull=(item->>3)::boolean
      and a.attnum>0 and not a.attisdropped and c.relowner=owner_oid and c.relkind='r' and c.relrowsecurity)
    then return false;end if;
 end loop;
 -- Diagnostic source + sealed Native forms; future actual application/transactions remain unexecuted.
 if private.ai_budget_source_ready() is not true then return false;end if;
 return true;
exception when others then return false;
end;
